import sys
M=10**9+7
def f(n):
    a,b=0,1
    for i in range(n.bit_length()-1,-1,-1):
        t=a*(2*b-a)%M
        u=(a*a+b*b)%M
        if n>>i&1:
            a,b=u,(t+u)%M
        else:
            a,b=t,u
    return a
sys.stdout.write('\n'.join(str(f(int(x))) for x in sys.stdin.read().split())+'\n')
